/* Piano About Me interaction — generated by install_piano_about.py */
(()=>{

const textLines=[
"Hi, I'm Yue, and I'm curious about how people build meaningful relationships with the technology around them.",
"I graduated with a master's degree in Computer Science from the University of Copenhagen, where I focused on Human-Computer Interaction.",
"I enjoy studying interaction through both theoretical reflection and creative, hands-on experimentation.",
"Critical making fascinates me because making things can also be a way of questioning the world around us.",
"I'm interested in social computing and how digital systems influence the way people communicate and collaborate.",
"Physical prototyping lets me bring abstract concepts into tangible experiences that people can touch and explore.",
"Animal-computer interaction makes me think about whose needs we consider when designing interactive technology.",
"I value empirical research because listening to people's experiences often leads to unexpected insights.",
"I like connecting design and research, using each to challenge and strengthen the other.",
"Everyday interactions interest me, especially the tiny details we rarely notice until something changes.",
"I love experimenting with creative ideas and turning open-ended questions into playful prototypes.",
"Ultimately, I hope to create and study interactive systems that enrich understanding and relationships in daily life."
];
const notes=[{n:'C',m:60,k:'A',white:0},{n:'C♯',m:61,k:'W',between:1},{n:'D',m:62,k:'S',white:1},{n:'D♯',m:63,k:'E',between:2},{n:'E',m:64,k:'D',white:2},{n:'F',m:65,k:'F',white:3},{n:'F♯',m:66,k:'T',between:4},{n:'G',m:67,k:'G',white:4},{n:'G♯',m:68,k:'Y',between:5},{n:'A',m:69,k:'H',white:5},{n:'A♯',m:70,k:'U',between:6},{n:'B',m:71,k:'J',white:6}];
const piano=document.getElementById('piano'),scroll=document.getElementById('scroll'),lines=document.getElementById('lines'),view=document.getElementById('view'),summary=document.getElementById('summary'),count=document.getElementById('count');const used=new Set();let finished=false,busy=false,audio,fadeTimer=0;const btns=[];
function context(){try{audio??=new (window.AudioContext||window.webkitAudioContext)();if(audio.state==='suspended')audio.resume();return audio}catch{return null}}
function tone(midi,t=0,dur=.78,volume=.13){const ctx=context();if(!ctx)return;const start=ctx.currentTime+t,f=440*Math.pow(2,(midi-69)/12);const o=ctx.createOscillator(),o2=ctx.createOscillator(),g=ctx.createGain();o.type='triangle';o2.type='sine';o.frequency.setValueAtTime(f,start);o2.frequency.setValueAtTime(f*2,start);g.gain.setValueAtTime(.0001,start);g.gain.exponentialRampToValueAtTime(volume,start+.018);g.gain.exponentialRampToValueAtTime(.001,start+dur);o.connect(g);o2.connect(g);g.connect(ctx.destination);o.start(start);o2.start(start);o.stop(start+dur+.04);o2.stop(start+dur+.04)}
function chord(){[[61,65,70,77],[60,65,69,75],[63,67,70,74]].forEach((arr,i)=>arr.forEach((n,j)=>tone(n,i*.45,1.4,.035)))}
function focus(index,behavior='smooth'){const el=document.querySelector('[data-note="'+index+'"]');if(!el)return;const target=scroll.scrollTop+(el.getBoundingClientRect().top+el.getBoundingClientRect().height/2)-(scroll.getBoundingClientRect().top+scroll.clientHeight/2);scroll.scrollTo({top:target,behavior});setTimeout(updateFocus,100);setTimeout(updateFocus,450)}
function updateFocus(){if(finished)return;const center=scroll.getBoundingClientRect().top+scroll.clientHeight/2;[...lines.children].forEach(e=>{let d=Math.abs(e.getBoundingClientRect().top+e.clientHeight/2-center);const strength=Math.max(0,1-d/190);e.classList.toggle('focus',strength>.7);e.style.opacity=(.15+.85*strength).toFixed(2);e.style.filter=`blur(${(1-strength)*1.4}px)`;e.style.transform=`scale(${(.96+.04*strength).toFixed(3)})`})}

function spawnFloatingNote(){
 const host=document.getElementById('music-particles');
 if(!host||window.matchMedia('(prefers-reduced-motion: reduce)').matches)return;
 const kind=Math.floor(Math.random()*5);
 const head=kind<2
   ? '<ellipse cx="13" cy="36" rx="9" ry="6.8" transform="rotate(-20 13 36)" fill="none" stroke="currentColor" stroke-width="2.7"/>'
   : '<ellipse cx="13" cy="36" rx="9" ry="6.8" transform="rotate(-20 13 36)" fill="currentColor"/>';
 const stem=kind===0?'':'<path d="M21 34 V7" fill="none" stroke="currentColor" stroke-width="2.7" stroke-linecap="round"/>';
 const flag=kind<3?'':kind===3
   ? '<path d="M21 7 C40 11 42 22 27 30 C34 21 28 17 21 15" fill="currentColor"/>'
   : '<path d="M21 7 C39 10 42 19 27 26 C34 18 28 15 21 14 Z M21 17 C39 20 41 29 26 36 C34 29 28 25 21 24 Z" fill="currentColor"/>';
 const el=document.createElement('span');
 el.className='floating-note';
 el.innerHTML='<svg viewBox="0 0 46 52" width="100%" height="100%" aria-hidden="true" xmlns="http://www.w3.org/2000/svg">'+head+stem+flag+'</svg>';
 el.style.setProperty('--note-x',(15+Math.random()*72)+'%');
 el.style.setProperty('--note-y',(45+Math.random()*42)+'%');
 el.style.setProperty('--note-size',(22+Math.random()*24)+'px');
 el.style.setProperty('--note-drift',(-42+Math.random()*84)+'px');
 el.style.setProperty('--note-duration',(1.8+Math.random()*.8)+'s');
 host.appendChild(el);
 el.addEventListener('animationend',()=>el.remove(),{once:true});
}
function press(i){spawnFloatingNote();tone(notes[i].m);const b=btns[i];b.classList.add('hit');setTimeout(()=>b.classList.remove('hit'),130);if(finished||busy)return;if(used.has(i)){focus(i);return;}used.add(i);b.classList.add('used');document.getElementById('empty').hidden=true;lines.hidden=false;const p=document.createElement('div');p.className='line new';p.dataset.note=i;p.textContent=textLines[i];lines.appendChild(p);count.firstChild.textContent=`${used.size} / 12 notes discovered `;requestAnimationFrame(()=>focus(i));setTimeout(updateFocus,630);if(used.size===12)setTimeout(()=>finish(false),1000)}
function finish(playChord){if(finished||busy)return;busy=true;if(playChord)chord();view.classList.add('finishing');setTimeout(()=>{view.classList.remove('finishing');view.classList.add('finished');finished=true;busy=false;summary.classList.add('on');count.firstChild.textContent='Introduction complete ♡ ';},380)}
notes.filter(n=>n.white!==undefined).forEach(n=>{const i=notes.indexOf(n),b=document.createElement('button');b.className='white';b.type='button';b.innerHTML=`<span>${n.n}</span>`;b.title=`${n.n} (${n.k})`;b.setAttribute('aria-label',`Play ${n.n}`);b.addEventListener('click',()=>press(i));piano.appendChild(b);btns[i]=b});notes.filter(n=>n.between!==undefined).forEach(n=>{const i=notes.indexOf(n),b=document.createElement('button');b.className='black';b.type='button';b.style.left=(n.between/7*100)+'%';b.title=`${n.n} (${n.k})`;b.setAttribute('aria-label',`Play ${n.n}`);b.addEventListener('click',()=>press(i));piano.appendChild(b);btns[i]=b});
scroll.addEventListener('scroll',updateFocus,{passive:true});document.getElementById('skip').addEventListener('click',()=>finish(true));document.getElementById('reset').addEventListener('click',()=>{used.clear();finished=false;busy=false;view.classList.remove('finished','finishing');summary.classList.remove('on');lines.innerHTML='';lines.hidden=true;document.getElementById('empty').hidden=false;btns.forEach(x=>x.classList.remove('used'));count.firstChild.textContent='0 / 12 notes discovered ';scroll.scrollTop=0});document.addEventListener('keydown',e=>{if(e.repeat)return;if(e.key==='Control'){e.preventDefault();finish(true);return}if(e.ctrlKey||e.altKey||e.metaKey||['INPUT','TEXTAREA'].includes(document.activeElement?.tagName))return;const i=notes.findIndex(n=>n.k.toLowerCase()===e.key.toLowerCase());if(i!==-1){e.preventDefault();press(i)}});

})();
